export class ErasureRepository {
  async create(client: PoolClient, merchantId: string, customerId: string): Promise<ErasureRequestRow> {
    const result = await client.query<ErasureRequestRow>(
      `INSERT INTO customers.erasure_requests(merchant_id,customer_id)
       VALUES($1,$2) RETURNING *`,
      [merchantId, customerId],
    );
    return result.rows[0]!;
  }

  async find(merchantId: string, requestId: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests WHERE merchant_id=$1 AND id=$2`,
      [merchantId, requestId],
    );
    return result.rows[0];
  }

  async findByCustomer(merchantId: string, customerId: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    return result.rows[0];
  }

  async markProcessing(client: PoolClient, requestId: string): Promise<void> {
    await client.query(
      `UPDATE customers.erasure_requests SET status='processing',updated_at=now()
       WHERE id=$1`,
      [requestId],
    );
  }

  async markFailed(client: PoolClient, requestId: string, error: string): Promise<void> {
    await client.query(
      `UPDATE customers.erasure_requests SET status='failed',attempts=attempts+1,
       last_error=$2,updated_at=now() WHERE id=$1`,
      [requestId, error],
    );
  }

  async markCompleted(client: PoolClient, requestId: string): Promise<void> {
    await client.query(
      `UPDATE customers.erasure_requests SET status='completed',attempts=attempts+1,
       completed_at=now(),updated_at=now() WHERE id=$1`,
      [requestId],
    );
  }

  async enqueueJob(
    client: PoolClient,
    merchantId: string,
    erasureRequestId: string,
    customerId: string,
  ): Promise<void> {
    await client.query(
      `INSERT INTO operations.jobs(queue,job_type,merchant_id,payload)
       VALUES('erasure','customer_erasure',$1,$2)`,
      [merchantId, { erasureRequestId, merchantId, customerId }],
    );
  }
}"}

{"command": "create", "path": "/workspace/source/apps/customer-service/src/erasure-service.ts", "file_text": "import { randomUUID } from 'node:crypto';
import type { PoolClient } from 'pg';
import { EVENT_TYPES } from '../../../packages/contracts/src/events.js';
import { transaction } from '../../../packages/database/src/pool.js';
import { addOutboxEvent } from '../../../packages/messaging/src/outbox.js';
import { CUSTOMER_INDEX, searchClient } from '../../../packages/search/src/client.js';
import { ErasureRepository, type ErasureRequestRow } from './erasure-repository.js';
import { CustomerRepository } from './repository.js';

export class ErasureService {
  constructor(
    private readonly repository = new CustomerRepository(),
    private readonly erasureRepo = new ErasureRepository(),
  ) {}

  async requestErasure(
    merchantId: string,
    customerId: string,
    idempotencyKey: string,
  ): Promise<ErasureRequestRow> {
    const customer = await this.repository.find(merchantId, customerId);
    if (!customer) throw Object.assign(new Error('customer_not_found'), { statusCode: 404 });

    const existing = await this.erasureRepo.findByCustomer(merchantId, customerId);

    return await transaction(async (client) => {
      const hash = await this.reserveIdempotency(client, merchantId, customerId, idempotencyKey);
      if (hash === 'existing') {
        return existing!;
      }

      if (existing) return existing;

      const request = await this.erasureRepo.create(client, merchantId, customerId);
      await this.erasureRepo.enqueueJob(client, merchantId, request.id, customerId);
      await addOutboxEvent(client, {
        eventType: EVENT_TYPES.CUSTOMER_ERASURE_REQUESTED,
        aggregateType: 'customer',
        aggregateId: customerId,
        merchantId,
        correlationId: randomUUID(),
        payload: { erasureRequestId: request.id, customerId },
      });
      return request;
    });
  }

  async getErasureRequest(merchantId: string, requestId: string): Promise<ErasureRequestRow> {
    const request = await this.erasureRepo.find(merchantId, requestId);
    if (!request) throw Object.assign(new Error('erasure_request_not_found'), { statusCode: 404 });
    return request;
  }

  async processErasure(erasureRequestId: string, merchantId: string, customerId: string): Promise<void> {
    await transaction(async (client) => {
      await this.erasureRepo.markProcessing(client, erasureRequestId);
    });

    try {
      await this.erasureCustomerData(merchantId, customerId);

      const correlationId = randomUUID();
      await transaction(async (client) => {
        await this.erasureRepo.markCompleted(client, erasureRequestId);
        await addOutboxEvent(client, {
          eventType: EVENT_TYPES.CUSTOMER_ERASED,
          aggregateType: 'customer',
          aggregateId: customerId,
          merchantId,
          correlationId,
          payload: { erasureRequestId, customerId },
        });
      });
    } catch (error) {
      const message = error instanceof Error ? error.message.slice(0, 300) : String(error).slice(0, 300);
      await transaction(async (client) => {
        await this.erasureRepo.markFailed(client, erasureRequestId, message);
      });
      throw error;
    }
  }

  private async erasureCustomerData(merchantId: string, customerId: string): Promise<void> {
    const pool = (await import('../../../packages/database/src/pool.js')).pool;

    // Redact PII from customers.customers - keep id, merchant_id, external_reference, status, metadata, version, timestamps
    await pool.query(
      `UPDATE customers.customers
       SET email='redacted@deleted.invalid', name='Deleted Customer', phone=NULL, updated_at=now()
       WHERE merchant_id=$1 AND id=$2`,
      [merchantId, customerId],
    );

    // Redact PII from addresses
    await pool.query(
      `UPDATE customers.addresses SET line1='REDACTED', line2=NULL, city='REDACTED', region=NULL, postal_code='00000'
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );

    // Redact PII from contacts
    await pool.query(
      `DELETE FROM customers.contacts WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );

    // Redact PII from payment_method_refs
    await pool.query(
      `UPDATE customers.payment_method_refs
       SET provider_token='redacted', brand=NULL, last4=NULL, billing_name=NULL, billing_address=NULL
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );

    // Redact PII from provider_customer_mappings
    await pool.query(
      `DELETE FROM customers.provider_customer_mappings
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );

    // Redact PII from provider_sandbox.customers
    await pool.query(
      `UPDATE provider_sandbox.customers
       SET email='redacted@deleted.invalid', name='Deleted Customer'
       WHERE merchant_id=$1 AND payflow_customer_id=$2`,
      [merchantId, customerId],
    );

    // Redact PII from payments.payment_intents customer_snapshot
    await pool.query(
      `UPDATE payments.payment_intents
       SET customer_snapshot=jsonb_set(
         jsonb_set(
           jsonb_set(customer_snapshot, '{email}', '"redacted@deleted.invalid"'),
           '{name}', '"Deleted Customer"'),
         '{phone}', 'null')
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );

    // Redact customer_email in refunds
    await pool.query(
      `UPDATE payments.refunds SET customer_email='redacted@deleted.invalid'
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );

    // Redact billing_snapshot in invoices
    await pool.query(
      `UPDATE payments.invoices
       SET billing_snapshot=jsonb_set(
         jsonb_set(billing_snapshot, '{email}', '"redacted@deleted.invalid"'),
         '{name}', '"Deleted Customer"')
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );

    // Redact document_manifests metadata
    await pool.query(
      `UPDATE operations.document_manifests SET customer_id=NULL
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );

    // Clear notification preferences
    await pool.query(
      `DELETE FROM operations.notification_preferences
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );

    // Clear analytics events email
    await pool.query(
      `UPDATE operations.analytics_events SET email=NULL
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );

    // Remove from search index
    try {
      await searchClient.delete({ index: CUSTOMER_INDEX, id: `${merchantId}:${customerId}` });
    } catch {
      // Index may not exist or document may already be absent - safe to ignore
    }

    // Clear Redis cache
    try {
      const { default: Redis } = await import('ioredis');
      const { config } = await import('../../../packages/config/src/index.js');
      const redis = new Redis(config().REDIS_URL);
      const cacheKey = `merchant:${merchantId}:customer:${customerId}`;
      await redis.del(cacheKey, `${cacheKey}:activity`);
      await redis.quit();
    } catch {
      // Redis may be unavailable - safe to ignore
    }
  }

  private async reserveIdempotency(
    client: PoolClient,
    merchantId: string,
    customerId: string,
    idempotencyKey: string,
  ): Promise<string> {
    const scope = 'customer-erasure';
    const { createHash } = await import('node:crypto');
    const hash = createHash('sha256').update(`${customerId}`).digest('hex');

    const existing = await client.query<{ request_hash: string; response_status: number | null }>(
      `SELECT request_hash,response_status FROM operations.idempotency_keys
       WHERE merchant_id=$1 AND scope=$2 AND key=$3 FOR UPDATE`,
      [merchantId, scope, idempotencyKey],
    );

    if (existing.rows[0]) {
      const row = existing.rows[0];
      if (row.request_hash !== hash) {
        throw Object.assign(new Error('idempotency key reused with different customer'), { statusCode: 409 });
      }
      if (row.response_status !== null) {
        return 'existing';
      }
      throw Object.assign(new Error('request with this idempotency key is in progress'), { statusCode: 409 });
    }

    await client.query(
      `INSERT INTO operations.idempotency_keys(merchant_id,scope,key,request_hash,expires_at)
       VALUES($1,$2,$3,$4,now()+interval '24 hours')`,
      [merchantId, scope, idempotencyKey, hash],
    );
    return hash;
  }
}"}

